CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TYPE user_role AS ENUM ('customer','provider','admin');
CREATE TYPE booking_status AS ENUM ('pending_payment','booked','in_progress','provider_completed','completed','canceled');
CREATE TABLE users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text NOT NULL, password_hash text NOT NULL, role user_role NOT NULL, display_name text NOT NULL, stripe_customer_id text UNIQUE, email_verified_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), disabled_at timestamptz);
CREATE UNIQUE INDEX users_email_unique ON users(lower(email));
CREATE TABLE sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users ON DELETE CASCADE, token_hash text NOT NULL UNIQUE, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE recovery_tokens (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users ON DELETE CASCADE, token_hash text NOT NULL UNIQUE, expires_at timestamptz NOT NULL, used_at timestamptz);
CREATE TABLE care_recipients (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), customer_id uuid NOT NULL REFERENCES users ON DELETE CASCADE, preferred_name text NOT NULL, relationship text, notes text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE provider_profiles (user_id uuid PRIMARY KEY REFERENCES users ON DELETE CASCADE, bio text NOT NULL DEFAULT '', experience_years integer CHECK(experience_years >= 0), service_zips text[] NOT NULL DEFAULT '{}', service_types text[] NOT NULL DEFAULT '{}', qualifications text[] NOT NULL DEFAULT '{}', availability jsonb NOT NULL DEFAULT '{}', verification_status text NOT NULL DEFAULT 'not_started' CHECK(verification_status IN ('not_started','pending','verified','rejected','expired')), credentials_verified_at timestamptz, stripe_account_id text UNIQUE, stripe_onboarding_complete boolean NOT NULL DEFAULT false, payments_enabled boolean NOT NULL DEFAULT false, rating numeric(2,1), review_count integer NOT NULL DEFAULT 0);
CREATE TABLE service_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), customer_id uuid NOT NULL REFERENCES users, care_recipient_id uuid NOT NULL REFERENCES care_recipients, service_type text NOT NULL, zip text NOT NULL, starts_at timestamptz NOT NULL, duration_minutes integer NOT NULL CHECK(duration_minutes > 0), clinical boolean NOT NULL DEFAULT false, required_qualifications text[] NOT NULL DEFAULT '{}', status text NOT NULL DEFAULT 'open' CHECK(status IN ('open','selected','booked','closed','canceled')), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE bookings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), request_id uuid NOT NULL UNIQUE REFERENCES service_requests, customer_id uuid NOT NULL REFERENCES users, provider_id uuid NOT NULL REFERENCES users, starts_at timestamptz NOT NULL, ends_at timestamptz NOT NULL, amount_cents integer NOT NULL CHECK(amount_cents > 0), commission_cents integer NOT NULL CHECK(commission_cents >= 0), status booking_status NOT NULL DEFAULT 'pending_payment', stripe_checkout_session_id text UNIQUE, stripe_payment_intent_id text UNIQUE, customer_confirmed_at timestamptz, completed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), CHECK(ends_at > starts_at));
CREATE UNIQUE INDEX no_active_provider_slot ON bookings(provider_id, starts_at, ends_at) WHERE status <> 'canceled';
CREATE TABLE reviews (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), booking_id uuid NOT NULL UNIQUE REFERENCES bookings, customer_id uuid NOT NULL REFERENCES users, provider_id uuid NOT NULL REFERENCES users, rating integer NOT NULL CHECK(rating BETWEEN 1 AND 5), body text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE memberships (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), customer_id uuid NOT NULL UNIQUE REFERENCES users, interval text NOT NULL CHECK(interval IN ('monthly','annual')), stripe_subscription_id text UNIQUE, status text NOT NULL DEFAULT 'pending', current_period_end timestamptz, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE webhook_events (stripe_event_id text PRIMARY KEY, event_type text NOT NULL, processed_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE notifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users ON DELETE CASCADE, kind text NOT NULL, subject text NOT NULL, body text NOT NULL, read_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE email_deliveries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), notification_id uuid NOT NULL REFERENCES notifications ON DELETE CASCADE, status text NOT NULL DEFAULT 'queued', attempts integer NOT NULL DEFAULT 0, next_attempt_at timestamptz NOT NULL DEFAULT now(), provider_message_id text, last_error text, updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX matching_idx ON provider_profiles USING gin(service_zips, service_types, qualifications);
